SELECT 
FROM exam_session s
WHERE s.id = #{id}
  AND s.user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE exam_session
SET status = 'SUBMITTED',
    submitted_at = #{submittedAt}
WHERE id = #{id}
  AND status IN ('CREATED', 'IN_PROGRESS')

UPDATE exam_session
SET status = 'SCORED',
    objective_score = #{objectiveScore},
    scored_at = #{scoredAt}
WHERE id = #{id}

